// Flatten all calculators into a master array of 465 items
const masterCalculators: any[] = [];
let idCounter = 1;

for (const group of categoryCalculatorDefs) {
  for (const c of group.calculators) {
    masterCalculators.push({
      id: String(idCounter++),
      name: c.name,
      slug: c.slug,
      description: c.description,
      category_slug: group.category_slug,
      formula: c.formula || '',
      is_featured: !!c.is_featured,
      is_popular: !!c.is_popular,
      sort_order: idCounter - 1,
      meta_title: `${c.name} - Free Online Calculator`,
      meta_description: c.description,
    });
  }
}

console.log(`Generated ${masterCalculators.length} calculators across ${categoryCalculatorDefs.length} categories.`);

const outPath = path.resolve(process.cwd(), 'src/data/allCalculatorsData.json');
fs.writeFileSync(outPath, JSON.stringify(masterCalculators, null, 2));
